    JSON.stringify(Object.keys(genCov).sort()) === JSON.stringify(Object.keys(WANT_HOL).sort()) && Object.entries(WANT_HOL).every(([ds, [sid, hol]]) => genCov[ds].surgeonId === sid && genCov[ds].holiday === hol)
