      const chip = (vacations, reqs, others = []) => { const all = [...reqs, ...others]; return chipIf({ reqs, pendingFloorBreach: mkMemo({ vacRequests: all, vacRequestCoverage: covFor(vacations, all) }) }); };
      const worst = covFor(fourOff, [r5])(r5);
